+#include "jvmti.h"
+#include "jvmti_common.hpp"
+
+#include <cstring>
+
+extern "C" {
+
+static jvmtiEnv* jvmti = nullptr;
+
+
+static jclass payload_class = nullptr;
+
+static jint events_count = 0;
+
+JNIEXPORT void JNICALL
+VMObjectAlloc(jvmtiEnv* jvmti_env,
+                   JNIEnv* jni,
+                   jthread thread,
+                   jobject object,
+                   jclass object_class,
+                   jlong size) {
+  if (jni->IsSameObject(object_class, payload_class)) {
+    jobject sample = jni->NewLocalRef(object);
+    if (sample == nullptr) {
+      jni->FatalError("Could not create object clone reference.");
+    }
+
+    events_count++;
+  }
+}
+
+JNIEXPORT jint JNICALL
+Java_VMObjectAllocCloneTest_eventsCount(JNIEnv* jni, jclass cls) {
+  return events_count;
+}
+
+
+JNIEXPORT void JNICALL
+Java_VMObjectAllocCloneTest_init(JNIEnv* env, jclass cls, jclass payload_cls) {
+  payload_class = (jclass)env->NewGlobalRef(payload_cls);
+  events_count = 0;
+}
+
+
+
+static jint Agent_Initialize(JavaVM* jvm, char* options, void* reserved) {
+  jint res = jvm->GetEnv((void**)&jvmti, JVMTI_VERSION_9);
+  if (res != JNI_OK || jvmti == nullptr) {
+    return JNI_ERR;
+  }
+
+  jvmtiCapabilities caps;
+  memset(&caps, 0, sizeof(caps));
+  caps.can_generate_vm_object_alloc_events = 1;
+  jvmtiError err = jvmti->AddCapabilities(&caps);
+  check_jvmti_error(err, "AddCapabilities");
+
+  jvmtiEventCallbacks callbacks;
+  memset(&callbacks, 0, sizeof(callbacks));
+  callbacks.VMObjectAlloc = &VMObjectAlloc;
+
+  err = jvmti->SetEventCallbacks(&callbacks, sizeof(callbacks));
+  check_jvmti_error(err, "SetEventCallbacks");
+
+  err = jvmti->SetEventNotificationMode(JVMTI_ENABLE, JVMTI_EVENT_VM_OBJECT_ALLOC , nullptr);
+  check_jvmti_error(err, "SetEventNotificationMode");
+
+  return JNI_OK;
+}
+
+JNIEXPORT jint JNICALL Agent_OnLoad(JavaVM* jvm, char* options, void* reserved) {
+  return Agent_Initialize(jvm, options, reserved);
+}
+
+JNIEXPORT jint JNICALL Agent_OnAttach(JavaVM* jvm, char* options, void* reserved) {
+  return Agent_Initialize(jvm, options, reserved);
+}
+
+}
